#include <string>

class Solution {
public:
    int firstMatchingChar(std::string s) {
        int n = s.length();
        int limit = n / 2 + (n % 2 != 0 ? 1 : 0);
        for (int i = 0; i < limit; ++i) {
            if (s[i] == s[n - 1 - i]) return i;
        }
        return -1;
    }
};

class Solution {
    public int firstMatchingChar(String s) {
        int n = s.length();
        int limit = n / 2 + (n % 2 != 0 ? 1 : 0);
        for (int i = 0; i < limit; i++) {
            if (s.charAt(i) == s.charAt(n - 1 - i)) return i;
        }
        return -1;
    }
}

function firstMatchingChar(s) {
    const n = s.length;
    const limit = Math.floor(n / 2) + (n % 2 !== 0 ? 1 : 0);
    for (let i = 0; i < limit; i++) {
        if (s[i] === s[n - 1 - i]) return i;
    }
    return -1;
}
